   if (pageIds.length === 0) return;
-  // Fire-and-forget on purpose. We deliberately do NOT return the promise.
-  void (async () => {
+  // Fire-and-forget on purpose. We deliberately do NOT return the promise,
+  // but we DO track it so cli.ts can drain before disconnect.
